        const done = this.tasks.filter(t => t.done).length;
        this.statsEl.textContent = total === 0 ? 'No tasks yet' : `${done} of ${total} completed`;
      }

      escapeHtml(str) {
        const div = document.createElement('div');
        div.textContent = str;
        return div.innerHTML;
      }
