  <h1>Task Dashboard</h1>
  <p class="subtitle">Organize your day, one task at a time</p>

  <div class="dashboard">
    <div class="input-row">
      <input type="text" id="taskInput" placeholder="Add a new task..." />
      <button class="btn btn-primary" id="addBtn">Add</button>
    </div>

    <div class="dashboard-header">
      <h2>Tasks</h2>
      <button class="btn btn-outline" id="clearBtn">Clear Done</button>
    </div>

    <ul class="task-list" id="taskList"></ul>

    <div class="stats" id="stats">
      <div>Total: <span>0</span></div>
      <div>Done: <span>0</span></div>
      <div>Left: <span>0</span></div>
    </div>
  </div>

  <script>
    class TaskManager {
      constructor() {
        this.tasks = [];
        this.nextId = 1;
        this.taskList = document.getElementById('taskList');
        this.taskInput = document.getElementById('taskInput');
        this.statsEl = document.getElementById('stats');
        document.getElementById('addBtn').addEventListener('click', () => this.add());
        document.getElementById('clearBtn').addEventListener('click', () => this.clearDone());
        this.taskInput.addEventListener('keydown', (e) => {
          if (e.key === 'Enter') this.add();
        });
      }

      add() {
        const text = this.taskInput.value.trim();
        if (!text) return;
        this.tasks.push({ id: this.nextId++, text, done: false });
        this.taskInput.value = '';
        this.render();
      }

      toggle(id) {
        const task = this.tasks.find(t => t.id === id);
        if (task) task.done = !task.done;
        this.render();
      }

      clearDone() {
        this.tasks = this.tasks.filter(t => !t.done);
        this.render();
      }

      render() {
        this.taskList.innerHTML = '';
        if (this.tasks.length === 0) {
          this.taskList.innerHTML = '<p class="empty-state">No tasks yet. Add one above!</p>';
        } else {
          this.tasks.forEach(task => {
            const li = document.createElement('li');
            li.className = 'task-item' + (task.done ? ' done' : '');
            li.innerHTML = `
              <input type="checkbox" class="task-checkbox" ${task.done ? 'checked' : ''} />
              <span class="task-text">${this.escapeHtml(task.text)}</span>
              <button class="task-remove">&times;</button>`;
            li.querySelector('.task-checkbox').addEventListener('change', () => this.toggle(task.id));
            li.querySelector('.task-remove').addEventListener('click', () => {
              this.tasks = this.tasks.filter(t => t.id !== task.id);
              this.render();
            });
            this.taskList.appendChild(li);
          });
        }
        const done = this.tasks.filter(t => t.done).length;
        this.statsEl.innerHTML = `<div>Total: <span>${this.tasks.length}</span></div><div>Done: <span>${done}</span></div><div>Left: <span>${this.tasks.length - done}</span></div>`;
      }

      escapeHtml(str) {
        const div = document.createElement('div');
        div.textContent = str;
        return div.innerHTML;
      }
    }

    const app = new TaskManager();
    app.render();
  </script>
