        const fake = this._currentUserCount();
        const card = this.cards.querySelector('[data-stat="active"]');
        if (card) card.textContent = fake.toLocaleString();
        this._addEntry(parseFloat((fake * 0.32).toFixed(2)).toFixed(2));
        setTimeout(() => this._tick(), 3000);
      }

      _currentUserCount() {
        return 1000 + Math.floor(Math.random() * 900);
