import { add, sub, mul, div } from './calc.js';
import { test } from 'node:test';
import assert from 'node:assert';

test('add returns the sum of two numbers', () => {
  assert.strictEqual(add(1, 2), 3);
  assert.strictEqual(add(-1, 1), 0);
  assert.strictEqual(add(0, 0), 0);
});

test('sub returns the difference of two numbers', () => {
  assert.strictEqual(sub(5, 3), 2);
  assert.strictEqual(sub(0, 5), -5);
  assert.strictEqual(sub(-3, -3), 0);
});

test('mul returns the product of two numbers', () => {
  assert.strictEqual(mul(3, 4), 12);
  assert.strictEqual(mul(-2, 5), -10);
  assert.strictEqual(mul(0, 100), 0);
});

test('div returns the quotient of two numbers', () => {
  assert.strictEqual(div(10, 2), 5);
  assert.strictEqual(div(7, 2), 3.5);
  assert.strictEqual(div(-10, 2), -5);
});

test('div throws on divide by zero', () => {
  assert.throws(() => div(10, 0), { message: 'Divide by zero' });
});

