/**
 * Adds two numbers and returns the result.
 * @param {number} a - The first operand.
 * @param {number} b - The second operand.
 * @returns {number} The sum of a and b.
 */
export function add(a, b) {
  return a + b;
}

/**
 * Subtracts b from a and returns the result.
 * @param {number} a - The first operand.
 * @param {number} b - The second operand.
 * @returns {number} The difference (a - b).
 */
export function sub(a, b) {
  return a - b;
}

/**
 * Multiplies two numbers and returns the result.
 * @param {number} a - The first operand.
 * @param {number} b - The second operand.
 * @returns {number} The product of a and b.
 */
export function mul(a, b) {
  return a * b;
}

/**
 * Divides a by b and returns the result.
 * Throws a TypeError if b is zero, since division by zero is undefined.
 * @param {number} a - The numerator.
 * @param {number} b - The denominator.
 * @returns {number} The quotient (a / b).
 * @throws {TypeError} Throws when b is zero.
 */
export function div(a, b) {
  if (b === 0) {
    throw new TypeError('Division by zero');
  }
  return a / b;
}

